body:
It seems to need at least some text element to work, so something like this work with both selection/caret and seem to correctly announce lines (only tested with macOS VoiceOver):

```diff
diff --git a/drivers/accesskit/accessibility_driver_accesskit.cpp b/drivers/accesskit/accessibility_driver_accesskit.cpp
index f4d6b7626a..f16f21ae98 100644
--- a/drivers/accesskit/accessibility_driver_accesskit.cpp
+++ b/drivers/accesskit/accessibility_driver_accesskit.cpp
@@ -421,39 +421,42 @@ RID AccessibilityDriverAccessKit::accessibility_create_sub_text_edit_elements(co

                run_off_x += size_x;
        }
-       if (!p_is_last_line) {
-               // Add "\n" at the end.
-               AccessibilityElement *ae = memnew(AccessibilityElement);
-               ae->role = ACCESSKIT_ROLE_TEXT_RUN;
-               ae->window_id = parent_ae->window_id;
-               ae->parent = root_rid;
-               ae->run = Vector3i(full_range.y, full_range.y, run_count);
-               ae->node = accesskit_node_new(ae->role);

-               text_elements.push_back(ae);
+       AccessibilityElement *ae = memnew(AccessibilityElement);
+       ae->role = ACCESSKIT_ROLE_TEXT_RUN;
+       ae->window_id = parent_ae->window_id;
+       ae->parent = root_rid;
+       ae->run = Vector3i(full_range.y, full_range.y, run_count);
+       ae->node = accesskit_node_new(ae->role);

-               Vector<uint8_t> char_lengths;
-               char_lengths.push_back(1);
+       text_elements.push_back(ae);
+
+       if (!p_is_last_line) {
                accesskit_node_set_value(ae->node, "\n");
-               accesskit_node_set_character_lengths(ae->node, char_lengths.size(), char_lengths.ptr());

                Vector<float> char_positions;
                Vector<float> char_widths;
+               Vector<uint8_t> char_lengths;
+               char_lengths.push_back(1);
                char_positions.push_back(0.0);
                char_widths.push_back(1.0);

+               accesskit_node_set_character_lengths(ae->node, char_lengths.size(), char_lengths.ptr());
                accesskit_node_set_character_positions(ae->node, char_positions.size(), char_positions.ptr());
                accesskit_node_set_character_widths(ae->node, char_widths.size(), char_widths.ptr());
-               accesskit_node_set_text_direction(ae->node, ACCESSKIT_TEXT_DIRECTION_LEFT_TO_RIGHT);
-
-               accesskit_rect rect;
-               rect.x0 = run_off_x;
-               rect.y0 = 0;
-               rect.x1 = run_off_x + 1;
-               rect.y1 = text_height;
-               accesskit_node_set_bounds(ae->node, rect);
+       } else {
+               accesskit_node_set_value(ae->node, "");
        }

+       accesskit_node_set_text_direction(ae->node, ACCESSKIT_TEXT_DIRECTION_LEFT_TO_RIGHT);
+
+       accesskit_rect rect;
+       rect.x0 = run_off_x;
+       rect.y0 = 0;
+       rect.x1 = run_off_x + 1;
+       rect.y1 = text_height;
+       accesskit_node_set_bounds(ae->node, rect);
+
        // Sort runs in logical order.
        struct RunCompare {
                _FORCE_INLINE_ bool operator()(const AccessibilityElement *l, const AccessibilityElement *r) const {
```
Adds empty element to the last line instead of `\n`.

Actually, it seems to be only needed if text is empty, seems like only it just needs to have at least one text element to work when control is selected, and for empty text `TextServer` return 0 runs..

```diff
diff --git a/drivers/accesskit/accessibility_driver_accesskit.cpp b/drivers/accesskit/accessibility_driver_accesskit.cpp
index f4d6b7626a..0749e873a3 100644
--- a/drivers/accesskit/accessibility_driver_accesskit.cpp
+++ b/drivers/accesskit/accessibility_driver_accesskit.cpp
@@ -421,7 +421,7 @@ RID AccessibilityDriverAccessKit::accessibility_create_sub_text_edit_elements(co

                run_off_x += size_x;
        }
-       if (!p_is_last_line) {
+       if (!p_is_last_line || text_elements.is_empty()) {
                // Add "\n" at the end.
                AccessibilityElement *ae = memnew(AccessibilityElement);
                ae->role = ACCESSKIT_ROLE_TEXT_RUN;
@@ -432,18 +432,22 @@ RID AccessibilityDriverAccessKit::accessibility_create_sub_text_edit_elements(co

                text_elements.push_back(ae);

-               Vector<uint8_t> char_lengths;
-               char_lengths.push_back(1);
-               accesskit_node_set_value(ae->node, "\n");
-               accesskit_node_set_character_lengths(ae->node, char_lengths.size(), char_lengths.ptr());
-
-               Vector<float> char_positions;
-               Vector<float> char_widths;
-               char_positions.push_back(0.0);
-               char_widths.push_back(1.0);
-
-               accesskit_node_set_character_positions(ae->node, char_positions.size(), char_positions.ptr());
-               accesskit_node_set_character_widths(ae->node, char_widths.size(), char_widths.ptr());
+               if (!p_is_last_line) {
+                       accesskit_node_set_value(ae->node, "\n");
+
+                       Vector<uint8_t> char_lengths;
+                       Vector<float> char_positions;
+                       Vector<float> char_widths;
+                       char_lengths.push_back(1);
+                       char_positions.push_back(0.0);
+                       char_widths.push_back(1.0);
+
+                       accesskit_node_set_character_lengths(ae->node, char_lengths.size(), char_lengths.ptr());
+                       accesskit_node_set_character_positions(ae->node, char_positions.size(), char_positions.ptr());
+                       accesskit_node_set_character_widths(ae->node, char_widths.size(), char_widths.ptr());
+               } else {
+                       accesskit_node_set_value(ae->node, "");
+               }
                accesskit_node_set_text_direction(ae->node, ACCESSKIT_TEXT_DIRECTION_LEFT_TO_RIGHT);

                accesskit_rect rect;
```
